#include <stdio.h>
#include <stdlib.h>

// Kruskal's algorithm for finding the Minimum Spanning Tree of a graph
void kruskal(int num_vertices, int num_edges, int edges[][3]) {
    int *parent = (int *)malloc(num_vertices * sizeof(int));
    for (int i = 0; i < num_vertices; i++) {
        parent[i] = i;
    }

    int num_tree_edges = 0;
    int tree_weight = 0;
    printf("weight=%d edges=", tree_weight);

    // Sort the edges in non-decreasing order of their weights
    for (int i = 0; i < num_edges; i++) {
        for (int j = i + 1; j < num_edges; j++) {
            if (edges[i][2] > edges[j][2]) {
                int temp = edges[i][0];
                edges[i][0] = edges[j][0];
                edges[j][0] = temp;
                temp = edges[i][1];
                edges[i][1] = edges[j][1];
                edges[j][1] = temp;
                temp = edges[i][2];
                edges[i][2] = edges[j][2];
                edges[j][2] = temp;
            }
        }
    }

    for (int i = 0; i < num_edges; i++) {
        int root1 = find(parent, edges[i][0]);
        int root2 = find(parent, edges[i][1]);

        if (root1 != root2) {
            printf("%d-%d", edges[i][0], edges[i][1]);
            putchar(',');
            tree_weight += edges[i][2];
            union_set(parent, root1, root2);
            num_tree_edges++;
        }
    }
    printf("\n");
}

int find(int *parent, int i) {
    if (parent[i] == i)
        return i;
    return find(parent, parent[i]);
}

void union_set(int *parent, int x, int y) {
    int xroot = find(parent, x);
    int yroot = find(parent, y);
    parent[xroot] = yroot;
}

int main(int argc, char **argv) {
    if (argc < 2) {
        printf("Usage: %s <number_of_vertices>\n", argv[0]);
        return 1;
    }
    int num_vertices = atoi(argv[1]);
    int num_edges = (num_vertices * (num_vertices - 1)) / 2;
    int edges[num_edges][3];
    int index = 0;
    for (int i = 0; i < num_vertices; i++) {
        for (int j = i + 1; j < num_vertices; j++) {
            edges[index][0] = i;
            edges[index][1] = j;
            edges[index][2] = rand() % 100; // Random weight between 0 and 99
            index++;
        }
    }
    kruskal(num_vertices, num_edges, edges);
    return 0;
}
